using System.ComponentModel;
using Microsoft.Extensions.AI;

// --- Tool implementations ---

var notes = new List<string>();

[Description("Search the web for information on a given query. Returns a list of relevant snippets.")]
string SearchWeb(string query)
{
    // In production, call a real search API (Bing, Google, etc.)
    Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
    return $"""
        Search results for "{query}":
        1. "{query}" is a widely discussed topic with recent advances reported in 2026.
        2. Key experts highlight breakthroughs in efficiency and scalability.
        3. Recent reviews note both promising applications and open challenges.
        (These are simulated results. Replace with a real search API for production use.)
        """;
}

[Description("Save a research note. Use this to record important findings during research.")]
string TakeNote(string note)
{
    notes.Add(note);
    Console.WriteLine($"  [Tool] Note saved ({notes.Count} total)");
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";
    return string.Join("\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

// --- Build the AI agent with tools ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "your-api-key-here";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(SearchWeb),
        AIFunctionFactory.Create(TakeNote),
        AIFunctionFactory.Create(GetNotes),
    ]
};

// --- Run the research agent ---

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var systemPrompt = $"""
    You are a research agent. Your goal is to research the following topic thoroughly
    and produce a well-organized summary.

    Topic: {topic}

    Instructions:
    1. Use the SearchWeb tool multiple times with different queries to gather information.
    2. Use the TakeNote tool to record key findings as you go.
    3. After gathering enough information (at least 3 searches), use GetNotes to review
       your findings, then provide a final comprehensive summary to the user.

    Be thorough but concise in your final summary.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research the topic \"{topic}\" and provide a summary of your findings.")
};

Console.WriteLine("Agent is working...\n");

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

if (notes.Count > 0)
{
    Console.WriteLine("\n=== Collected Notes ===");
    for (int i = 0; i < notes.Count; i++)
        Console.WriteLine($"  {i + 1}. {notes[i]}");
}

